const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for similar products - tees, tops, cotton items that are in stock
const products = db.prepare(\"
  SELECT product_id, name, category, subcategory, brand, price, current_price, in_stock, stock_quantity, variants_json
  FROM products
  WHERE in_stock = 1
    AND (
      LOWER(name) LIKE '%tee%'
      OR LOWER(name) LIKE '%crew%'
      OR LOWER(name) LIKE '%cotton%'
      OR LOWER(name) LIKE '%top%'
      OR LOWER(name) LIKE '%t-shirt%'
      OR LOWER(name) LIKE '%tshirt%'
      OR LOWER(name) LIKE '%shirt%'
    )
  ORDER BY name
\").all();

console.log('=== In-Stock Products matching tee/crew/cotton/top/shirt ===');
console.log('Found:', products.length, 'products\n');
for (const p of products) {
  const variants = JSON.parse(p.variants_json || '[]');
  console.log('- ' + p.product_id + ' | ' + p.name + ' | \$' + (p.current_price || p.price) + ' | Stock: ' + p.stock_quantity + ' | Variants in product: ' + variants.length);
}
"

