const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const productIds = ['6043535048','2575138841','6897421911','7997630580','2460285426','4244521606','PROD-39F904'];

for (const pid of productIds) {
  const variants = db.prepare(\"SELECT item_id, options, available, price FROM rt_variants WHERE product_id = ? AND available = 1\").all(pid);
  if (variants.length > 0) {
    const product = db.prepare(\"SELECT name, price, current_price FROM products WHERE product_id = ?\").get(pid);
    console.log('=== ' + product.name + ' (' + pid + ') - Base price: \$' + (product.current_price || product.price) + ' ===');
    for (const v of variants) {
      console.log('  Variant: ' + v.item_id + ' | Price: \$' + v.price + ' | Options: ' + v.options);
    }
    console.log('');
  }
}

// Also check if ANY clothing product has rt_variants
const allClothingWithVariants = db.prepare(\"SELECT DISTINCT p.product_id, p.name, p.price, p.current_price FROM products p INNER JOIN rt_variants v ON p.product_id = v.product_id WHERE p.in_stock = 1 AND p.category = 'clothing' AND v.available = 1\").all();
console.log('=== All in-stock clothing with available rt_variants ===');
for (const p of allClothingWithVariants) {
  const variants = db.prepare(\"SELECT item_id, options, price FROM rt_variants WHERE product_id = ? AND available = 1\").all(p.product_id);
  console.log(p.product_id + ' | ' + p.name + ' | \$' + (p.current_price || p.price) + ' | ' + variants.length + ' variant(s)');
  for (const v of variants) {
    console.log('    ' + v.item_id + ' | \$' + v.price + ' | ' + v.options);
  }
}
"

